reactiveclass Hub {
	statevars {
		Client clients[5];
		int clientCount;
	}

	knownrebecs { }

	Hub() {
		clientCount = 0;
	}

	msghandler Register(Client ref) {
		if (clientCount < 5) {
			clients[clientCount] = ref;
			clientCount = clientCount + 1;
		}
	}

	msghandler Ping() {
		sender.Pong();
	}
}

main {
	Hub hub():();
	Client c1(hub):();
	Client c2(hub):();
	Client c3(hub):();
	Client c4(hub):();
	Client c5(hub):();

